import{_ as r,a0 as m,w as s,s as l,ao as p,I as e,x as n,a1 as i,A as t}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"Linux系统 whoami 命令 – 知晓当前登录用户 | LCTT x X-CMD","titleTemplate":false,"description":"Linux系统 whoami 命令 – 知晓当前登录用户 | LCTT (201312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux系统 whoami 命令 – 知晓当前登录用户 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux系统 whoami 命令 – 知晓当前登录用户 | LCTT (201312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201312/Linux whoami command – Knowing Who is Logged In","title":"Linux系统 whoami 命令 – 知晓当前登录用户","tag":"201312","desc":""},"relativePath":"201312/Linux whoami command – Knowing Who is Logged In.md","filePath":"[post].md"}'),h={name:"201312/Linux whoami command – Knowing Who is Logged In.md"};function d(w,o,u,g,x,c){const a=m("Link");return s(),l("div",null,[o[11]||(o[11]=p(`<h1 id="linux系统-whoami-命令-–-知晓当前登录用户" tabindex="-1">Linux系统 whoami 命令 – 知晓当前登录用户 <a class="header-anchor" href="#linux系统-whoami-命令-–-知晓当前登录用户" aria-label="Permalink to “Linux系统 whoami 命令 – 知晓当前登录用户”">​</a></h1><p>通常，在控制台的命令提示符下你会发现 <strong>用户名已经被显示出来</strong> 。但有一些 shell 默认情况下不会显示你的用户名，比如 <strong>csh</strong> 。所以这个命令最应该用在那些不能回显用户名的 shell 终端上。</p><h3 id="怎么样运行-whoami" tabindex="-1">怎么样运行 whoami <a class="header-anchor" href="#怎么样运行-whoami" aria-label="Permalink to “怎么样运行 whoami”">​</a></h3><p>运行这个命令，你只需要输入 whoami 。下面的例子中我们使用的是 csh shell 终端。</p><pre><code>% whoami
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/csh.png" alt=""></p><h3 id="whoami-的参数选项" tabindex="-1">Whoami 的参数选项 <a class="header-anchor" href="#whoami-的参数选项" aria-label="Permalink to “Whoami 的参数选项”">​</a></h3><p>这个命令仅仅有两个参数选项： <strong>–help</strong> 和 <strong>–version</strong>。</p><pre><code>% whoamin –help
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/whoami_help.png" alt=""></p><p>下面这选项会输出和 <strong>man whoami</strong> 命令一样的信息</p><pre><code>% whoami –version
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/whoami_version.png" alt=""></p><p>不同的是 <strong>–version</strong> 会显示你系统上 whoami 命令的版本信息</p><h3 id="相似性" tabindex="-1">相似性 <a class="header-anchor" href="#相似性" aria-label="Permalink to “相似性”">​</a></h3><p>whoami 命令和 <strong>id -un</strong> 有相同的输出。它们都显示出当前用户的用户名。</p><pre><code>% id -un
</code></pre><p><img src="http://linoxide.com/wp-content/uploads/2013/12/id-un.png" alt=""></p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>whoami 命令也用于当你使用 su 命令（切换用户）时, 它能让你确认登录的用户名是否正确。whoami 和 who 命令不相同， who 命令会显示所有已经登录的用户名，而 whoami 不是。当你切换用户时，whoami 命令会显示会话所属的当前用户，而 who 命令会显示你切换前的那个源用户。</p><p><img src="http://linoxide.com/wp-content/uploads/2013/12/whoami_vs_who.png" alt=""></p><hr>`,22)),e("p",null,[o[1]||(o[1]=n("via: ",-1)),i(a,{href:"http://linoxide.com/linux-command/linux-whoami-command/"},{default:t(()=>[...o[0]||(o[0]=[n("http://linoxide.com/linux-command/linux-whoami-command/",-1)])]),_:1})]),e("p",null,[o[4]||(o[4]=n("译者：",-1)),i(a,{href:"https://github.com/runningwater"},{default:t(()=>[...o[2]||(o[2]=[n("runningwater",-1)])]),_:1}),o[5]||(o[5]=n(" 校对：",-1)),i(a,{href:"https://github.com/carolinewuyan"},{default:t(()=>[...o[3]||(o[3]=[n("Caroline",-1)])]),_:1})]),e("p",null,[o[8]||(o[8]=n("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...o[6]||(o[6]=[n("LCTT",-1)])]),_:1}),o[9]||(o[9]=n(" 原创翻译，",-1)),i(a,{href:"http://linux.cn/"},{default:t(()=>[...o[7]||(o[7]=[n("Linux中国",-1)])]),_:1}),o[10]||(o[10]=n(" 荣誉推出",-1))])])}const _=r(h,[["render",d]]);export{T as __pageData,_ as default};
